// Utility to generate formatted resume documents and trigger Download / Print to PDF

const TEMPLATE_STYLES = {
  1: {
    name: 'Classic Professional',
    fontFamily: 'Georgia, "Times New Roman", serif',
    primaryColor: '#1f2f4d',
    secondaryColor: '#4f7cff',
    accentColor: '#eef2ff',
    headerBg: '#f8fafc',
    headerBorder: '#1f2f4d',
  },
  2: {
    name: 'Modern Minimalist',
    fontFamily: '"Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
    primaryColor: '#0f766e',
    secondaryColor: '#0d9488',
    accentColor: '#f0fdfa',
    headerBg: '#f0fdfa',
    headerBorder: '#0d9488',
  },
  3: {
    name: 'Creative Portfolio',
    fontFamily: '"Poppins", "Inter", sans-serif',
    primaryColor: '#b91c1c',
    secondaryColor: '#e11d48',
    accentColor: '#fff1f2',
    headerBg: '#fff1f2',
    headerBorder: '#e11d48',
  },
  4: {
    name: 'Executive Suite',
    fontFamily: '"Merriweather", Georgia, serif',
    primaryColor: '#1e293b',
    secondaryColor: '#b45309',
    accentColor: '#fffbeb',
    headerBg: '#fafaf9',
    headerBorder: '#b45309',
  },
  5: {
    name: 'Healthcare Clean',
    fontFamily: '"Roboto", -apple-system, sans-serif',
    primaryColor: '#0369a1',
    secondaryColor: '#0284c7',
    accentColor: '#f0f9ff',
    headerBg: '#f0f9ff',
    headerBorder: '#0284c7',
  },
  6: {
    name: 'Startup Bold',
    fontFamily: '"Montserrat", "Inter", sans-serif',
    primaryColor: '#6d28d9',
    secondaryColor: '#7c3aed',
    accentColor: '#f5f3ff',
    headerBg: '#f5f3ff',
    headerBorder: '#7c3aed',
  },
};

const DEFAULT_STYLE = {
  name: 'Default',
  fontFamily: '"Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
  primaryColor: '#1f2430',
  secondaryColor: '#4f7cff',
  accentColor: '#eef2ff',
  headerBg: '#ffffff',
  headerBorder: '#4f7cff',
};

export function generateResumeHtml(resume) {
  const tId = Number(resume.templateId);
  const style = TEMPLATE_STYLES[tId] || DEFAULT_STYLE;

  const candidateName = escapeHtml(resume.candidateName || resume.title || 'Untitled Resume');
  const headline = escapeHtml(resume.headline || '');
  const summary = escapeHtml(resume.summary || '');
  const contactEmail = escapeHtml(resume.contactEmail || '');
  const contactPhone = escapeHtml(resume.contactPhone || '');
  const location = escapeHtml(resume.location || '');
  const address = escapeHtml(resume.address || '');
  const linkedInUrl = escapeHtml(resume.linkedInUrl || '');
  const portfolioUrl = escapeHtml(resume.portfolioUrl || '');
  const skills = Array.isArray(resume.skills) ? resume.skills : [];
  const experience = Array.isArray(resume.experience) ? resume.experience : [];
  const education = Array.isArray(resume.education) ? resume.education : [];

  const contactItems = [];
  if (contactEmail) {
    contactItems.push(`<a href="mailto:${contactEmail}">✉ ${contactEmail}</a>`);
  }
  if (contactPhone) {
    contactItems.push(`<span>📞 ${contactPhone}</span>`);
  }
  if (location) {
    contactItems.push(`<span>📍 ${location}</span>`);
  }
  if (address) {
    contactItems.push(`<span>🏠 ${address}</span>`);
  }
  if (linkedInUrl) {
    const display = linkedInUrl.replace(/^https?:\/\/(www\.)?linkedin\.com\/in\//i, 'in/');
    contactItems.push(`<a href="${linkedInUrl}" target="_blank" rel="noopener noreferrer">🔗 ${display}</a>`);
  }
  if (portfolioUrl) {
    const display = portfolioUrl.replace(/^https?:\/\/(www\.)?/i, '');
    contactItems.push(`<a href="${portfolioUrl}" target="_blank" rel="noopener noreferrer">🌐 ${display}</a>`);
  }

  const experienceHtml = experience.length > 0 ? `
    <section class="resume-section">
      <h2 class="section-title">Professional Experience</h2>
      <div class="entries">
        ${experience.map((exp) => {
          const dateRange = [exp.startDate, exp.current ? 'Present' : exp.endDate].filter(Boolean).join(' – ');
          const formattedDesc = escapeHtml(exp.description || '')
            .split('\n')
            .filter((l) => l.trim().length > 0)
            .map((line) => line.startsWith('•') || line.startsWith('-') ? `<li>${line.replace(/^[•\-]\s*/, '')}</li>` : `<p>${line}</p>`)
            .join('');
          const descOutput = formattedDesc.includes('<li>') ? `<ul>${formattedDesc}</ul>` : formattedDesc;

          return `
            <div class="entry">
              <div class="entry-header">
                <div>
                  <h3 class="entry-role">${escapeHtml(exp.jobTitle || 'Role')}</h3>
                  <div class="entry-subtitle">${escapeHtml(exp.company || '')}</div>
                </div>
                ${dateRange ? `<div class="entry-date">${escapeHtml(dateRange)}</div>` : ''}
              </div>
              ${descOutput ? `<div class="entry-desc">${descOutput}</div>` : ''}
            </div>
          `;
        }).join('')}
      </div>
    </section>
  ` : '';

  const educationHtml = education.length > 0 ? `
    <section class="resume-section">
      <h2 class="section-title">Education</h2>
      <div class="entries">
        ${education.map((edu) => {
          const dateRange = [edu.startDate, edu.endDate].filter(Boolean).join(' – ');
          const degreeAndField = [edu.degree, edu.fieldOfStudy].filter(Boolean).join(' in ');
          return `
            <div class="entry">
              <div class="entry-header">
                <div>
                  <h3 class="entry-role">${escapeHtml(edu.institution || 'University / Institution')}</h3>
                  ${degreeAndField ? `<div class="entry-subtitle">${escapeHtml(degreeAndField)}</div>` : ''}
                </div>
                ${dateRange ? `<div class="entry-date">${escapeHtml(dateRange)}</div>` : ''}
              </div>
